def _normalize_ttl(ttl: int | None) -> int | None:
    """
    把 ``None`` / ``-1`` / ``0`` 统一为「不设置过期」。
    正整数原样返回（至少 1 秒，Redis 不允许 EX 0）。
    """
    if ttl is None or ttl == TTL_NEVER_EXPIRE or ttl == 0:
        return None
    return max(1, ttl)

